/* Stage-one optical motion. Progressive enhancement with a shared motion preference. */
(()=>{
 const enabled=()=>document.documentElement.dataset.motion!=='off'&&!matchMedia('(prefers-reduced-motion:reduce)').matches;
 const menu=document.querySelector('#space-navigator');
 new MutationObserver(()=>{if(menu.open&&enabled())menu.querySelectorAll('.space-grid>a').forEach((el,i)=>el.animate([{opacity:0,transform:'translateY(25px)'},{opacity:1,transform:'none'}],{duration:650,delay:i*45,easing:'cubic-bezier(.16,1,.3,1)',fill:'backwards'}))}).observe(menu,{attributes:true,attributeFilter:['open']});
 document.addEventListener('click',ev=>{const button=ev.target.closest('.button,.dream-lens-controls button,.dream-menu-trigger');if(!button||!enabled())return;const r=button.getBoundingClientRect(),pulse=document.createElement('i');pulse.className='dream-button-pulse';pulse.setAttribute('aria-hidden','true');pulse.style.left=(ev.detail?ev.clientX-r.left:r.width/2)+'px';pulse.style.top=(ev.detail?ev.clientY-r.top:r.height/2)+'px';button.append(pulse);const animation=pulse.animate([{opacity:.3,transform:'translate(-50%,-50%) scale(0)'},{opacity:0,transform:'translate(-50%,-50%) scale(1)'}],{duration:650,easing:'ease-out'});animation.finished.catch(()=>{}).finally(()=>pulse.remove())});
 let frame=0;const update=()=>{frame=0;const hero=document.querySelector('.dream-hero');if(!hero)return;const p=enabled()?Math.min(1,Math.max(0,scrollY/hero.offsetHeight)):0;hero.style.setProperty('--hero-scroll',p);document.querySelectorAll('.dream-orbit-symbol,.dream-space-art,.dream-finale-word').forEach(el=>{const r=el.getBoundingClientRect(),progress=enabled()?Math.max(-1,Math.min(1,(r.top+r.height/2-innerHeight/2)/innerHeight)):0;el.style.translate='0 '+(-progress*32)+'px';if(el.matches('.dream-orbit-symbol'))el.style.rotate=progress*35+'deg'})};
 const queue=()=>{if(!frame)frame=requestAnimationFrame(update)};addEventListener('scroll',queue,{passive:true});addEventListener('rrh:route',queue);addEventListener('rrh:motion',()=>{document.querySelectorAll('.dream-button-pulse').forEach(el=>el.remove());if(!enabled())menu.getAnimations({subtree:true}).forEach(a=>a.finish());queue()});queue();
})();
